curl -s -X POST "https://slack.com/api/conversations.list?token=<TOKEN>&types=public_channel,private_channel&limit=1000" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit()
for c in d['channels']:
    if 'release' in c['name'].lower():
        print(c['id'], c['name'], c.get('is_archived', False))
"

