arguments.command:
curl -s -X POST "https://slack.com/api/users.list?token=<TOKEN>&limit=0" | python3 -c "
import json,sys
d=json.load(sys.stdin)
if not d.get('ok'): print('ERR', d); sys.exit()
for u in d['members']:
    prof = u.get('profile', {})
    email = prof.get('email') or ''
    if 'lena.hart' in email.lower():
        print(u['id'], u['deleted'], email, prof.get('real_name'), prof.get('title'))
"

